15	// ── Data model ────────────────────────────────────────────────────────────────
16	
17	enum Card {
18	    RepoLink   { name: String, dir: String, branch: String },
19	    Header     { title: Option<String>, cwd: String, branch: String, ts: String, agent: String },
20	    UserMsg    { ts: String, parts: Vec<UserPart>, author: Option<String> },
21	    AsstMsg    { ts: String, parts: Vec<AsstPart> },
22	    ToolRound  { parts: Vec<AsstPart> },
23	    System     { ts: String, subtype: String, content: String },
24	    Checkpoint(CheckpointData),
25	}
26	
27	struct CheckpointData {
28	    number:              u32,
29	    checkpoint_id:       String,
30	    commit_sha:          String,
31	    repo_dir:            String,
32	    commit_message:      String,
33	    last_turn_ts:        String,
34	    author_name:         String,
35	    author_email:        String,
36	    files_touched:       Vec<String>,
37	    token_usage:         Option<TokenUsage>,
38	    initial_attribution: Option<InitialAttribution>,
39	    model:               String,
40	}
41	
42	struct TokenUsage {
43	    input_tokens:           i64,
44	    cache_creation_tokens:  i64,
45	    cache_read_tokens:      i64,
46	    output_tokens:          i64,
47	    api_call_count:         i64,
48	}
49	
50	struct InitialAttribution {
51	    human_added:         i64,
52	    human_modified:      i64,
53	    human_removed:       i64,
54	    total_committed:     i64,
55	    total_lines_changed: i64,
56	    agent_percentage:    f64,
57	}
58	
59	/// One entry per checkpoint commit, ordered oldest first. A turn with
60	/// timestamp T is attributed to the first entry whose `last_turn_ts >= T`.
61	struct CheckpointAuthor {
62	    last_turn_ts: DateTime<Utc>,
63	    label: String, // display name; email as fallback
64	}
65	
66	enum UserPart {
67	    Text(String),
68	    ToolResult { id: String, name: String, content: String, is_error: bool },
69	}
70	
71	enum AsstPart {
72	    Text(String),
73	    ToolCall { id: String, name: String, input: Value, result: Option<(String, bool)> },
74	}
75	
76	#[derive(Clone, PartialEq)]
77	enum Selectable {
78	    Card(usize),
79	    ToolHeader(usize),
80	    ToolCall(usize, usize),        // (card_idx, tool_idx)
81	    CheckpointHeader(usize),
82	    CheckpointFile(usize, usize),  // (card_idx, file_idx)
83	}
84	
85	// ── Entry point ───────────────────────────────────────────────────────────────
86	
87	/// Returns `Ok(true)` if the user pressed `q` (or Ctrl+C) — callers in a
88	/// parent TUI loop should treat that as a full-app exit. `Ok(false)` means
89	/// the user backed out normally (Esc/Left) and the parent should keep going.
90	pub fn run(session_id: &str) -> Result<bool> {
91	    run_at(session_id, None, None, None, None)
92	}
93	
94	/// Open a session and jump to a specific turn or checkpoint.
95	/// `turn_id`      — JSONL message uuid (stable across file versions).
96	/// `hit_ts`       — raw timestamp string fallback.
97	/// `hit_off`      — byte offset of the matched JSONL line (most reliable; bypasses string matching).
98	/// `checkpoint_id`— navigate directly to the matching Checkpoint card.
99	pub fn run_at(session_id: &str, turn_id: Option<&str>, hit_ts: Option<&str>, hit_off: Option<u64>, checkpoint_id: Option<&str>) -> Result<bool> {
100	    let path = find_session(session_id)
101	        .with_context(|| format!("no session file found for '{session_id}'"))?;
102	
103	    let raw = std::fs::read_to_string(&path)
104	        .with_context(|| format!("cannot read {}", path.display()))?;
105	
106	
107	    // Resolve to a timestamp for pager navigation.
108	    // Priority: raw hit_ts (directly from witchcraft metadata, same source as
109	    // the JSONL timestamp field) → uuid scan of local file → byte-offset scan
110	    // (hit_off is relative to the shadow-branch copy, so only use as a last
111	    // resort when the other two come up empty).
112	    let resolved_ts: Option<String> = hit_ts.map(str::to_string)
113	        .or_else(|| turn_id.and_then(|tid| {
114	            for line in raw.lines() {
115	                let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
116	                if v["uuid"].as_str() == Some(tid) {
117	                    return v["timestamp"].as_str().map(str::to_string);
118	                }
119	            }
120	            None
121	        }))
122	        .or_else(|| hit_off.and_then(|off| {
123	            let bytes = raw.as_bytes();
124	            if (off as usize) < bytes.len() {
125	                let slice = &bytes[off as usize..];
126	                let end = slice.iter().position(|&b| b == b'\n').unwrap_or(slice.len());
127	                std::str::from_utf8(&slice[..end]).ok()
128	                    .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
129	                    .and_then(|v| v["timestamp"].as_str().map(str::to_string))
130	            } else { None }
131	        }));
132	    let start_ts: Option<&str> = resolved_ts.as_deref();
133	
134	    // Look up agent name and DB-stored session_name from the gossamer DB.
135	    let uuid = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
136	    let (agent, db_session_name) = if let Ok(conn) = crate::db::connect() {
137	        conn.query_row(
138	            "SELECT agent_name, COALESCE(session_name, '') FROM sessions WHERE session_id = ?1",
139	            [uuid],
140	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
141	        ).unwrap_or_default()
142	    } else { (String::new(), String::new()) };
143	
144	    let mut cards = parse(&raw, &agent);
145	    if cards.is_empty() {
146	        println!("No messages found.");
147	        return Ok(false);
148	    }
149	
150	    let checkpoints = fetch_checkpoints(uuid);
151	    if !checkpoints.is_empty() {
152	        insert_checkpoints(&mut cards, checkpoints);
153	    }
154	
155	    // Title fallback chain: JSONL custom-title (already set by parse) →
156	    // DB session_name (the indexer's first-meaningful-prompt) → first user
157	    // prompt in the JSONL. Covers sessions that were never /rename'd.
158	    let mut need_prompt_fallback = false;
159	    if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
160	        if title.as_deref().map_or(true, str::is_empty) {
161	            if !db_session_name.trim().is_empty() {
162	                *title = Some(db_session_name);
163	            } else {
164	                need_prompt_fallback = true;
165	            }
166	        }
167	    }
168	    if need_prompt_fallback {
169	        let first_user_text: Option<String> = cards.iter().find_map(|c| {
170	            if let Card::UserMsg { parts, .. } = c {
171	                parts.iter().find_map(|p| {
172	                    if let UserPart::Text(t) = p {
173	                        let trimmed = t.trim();
174	                        if trimmed.is_empty() { None } else { Some(trimmed.to_string()) }
175	                    } else { None }
176	                })
177	            } else { None }
178	        });
179	        if let Some(text) = first_user_text {
180	            if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
181	                *title = Some(text);
182	            }
183	        }
184	    }
185	
186	    // Extract branch and cwd from the Header before cards are consumed by pager.
187	    let session_branch = cards.iter().find_map(|c| {
188	        if let Card::Header { branch, .. } = c { Some(branch.clone()) } else { None }
189	    }).unwrap_or_default();
190	    let session_cwd = cards.iter().find_map(|c| {
191	        if let Card::Header { cwd, .. } = c { Some(cwd.clone()) } else { None }
192	    }).unwrap_or_default();
193	
194	    // Attribute each user message to the checkpoint author, or fall back to
195	    // git config user.name for sessions not yet indexed from the checkpoint branch.
196	    let authors = fetch_authors(uuid);
197	    if !authors.is_empty() {
198	        for card in cards.iter_mut() {
199	            if let Card::UserMsg { ts, author, .. } = card {
200	                *author = attribute(&authors, ts);
201	            }
202	        }
203	    } else if let Some(name) = git_config_user(&session_cwd) {
204	        for card in cards.iter_mut() {
205	            if let Card::UserMsg { author, .. } = card {
206	                *author = Some(name.clone());
207	            }
208	        }
209	    }
210	
211	    // Look up the repo that owns this session's cwd and prepend a RepoLink card.
212	    if let Ok(conn) = crate::db::connect() {
213	        if let Ok((repo_name, repo_dir)) = conn.query_row(
214	            "SELECT name, directory FROM repositories
215	             WHERE ?1 LIKE (directory || '%')
216	             ORDER BY LENGTH(directory) DESC LIMIT 1",
217	            [&session_cwd],
218	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
219	        ) {
220	            cards.insert(0, Card::RepoLink { name: repo_name, dir: repo_dir, branch: session_branch.clone() });
221	        }
222	    }
223	
224	    let mut quit_app = false;
225	    loop {
226	        match pager(&cards, start_ts, checkpoint_id, hit_off)? {
227	            PagerOutcome::Resume => {
228	                do_resume(&agent, session_id, &session_branch, &session_cwd);
229	                break;
230	            }
231	            PagerOutcome::Delete => { super::clean::run(session_id, false)?; break; }
232	            PagerOutcome::Quit   => { quit_app = true; break; }
233	            PagerOutcome::Back   => break,
234	            PagerOutcome::GoToSessions => {
235	                if super::sessions::run(false, false)? { quit_app = true; }
236	                break;
237	            }
238	            PagerOutcome::GoToRepo(dir) => {
239	                if super::status::run_for_dir(&dir)? { quit_app = true; break; }
240	            }
241	        }
242	    }
243	
244	    Ok(quit_app)
245	}
246	
247	fn fetch_authors(session_id: &str) -> Vec<CheckpointAuthor> {
248	    let Ok(conn) = crate::db::connect() else { return Vec::new(); };
249	    let Ok(mut stmt) = conn.prepare(
250	        "SELECT last_turn_ts, author_name, author_email, COALESCE(os_user, '')
251	           FROM checkpoints
252	          WHERE session_id = ?1
253	       ORDER BY last_turn_ts ASC"
254	    ) else { return Vec::new(); };
255	
256	    let rows = stmt.query_map([session_id], |row| {
257	        let ts: String = row.get(0)?;
258	        let name: String = row.get(1)?;
259	        let email: String = row.get(2)?;
260	        let os_user: String = row.get(3)?;
261	        Ok((ts, name, email, os_user))
262	    });
263	    let Ok(rows) = rows else { return Vec::new(); };
264	
265	    let mut out = Vec::new();
266	    for r in rows.flatten() {
267	        let (ts_s, name, email, os_user) = r;
268	        let Ok(dt) = DateTime::parse_from_rfc3339(&ts_s) else { continue };
269	        let label = if !name.trim().is_empty() {
270	            name
271	        } else if !email.trim().is_empty() {
272	            email
273	        } else {
274	            os_user
275	        };
276	        if label.is_empty() { continue; }
277	        out.push(CheckpointAuthor {
278	            last_turn_ts: dt.with_timezone(&Utc),
279	            label,
280	        });
281	    }
282	    out
283	}
284	
285	fn attribute(authors: &[CheckpointAuthor], ts: &str) -> Option<String> {
286	    let dt = DateTime::parse_from_rfc3339(ts).ok()?.with_timezone(&Utc);
287	    // Earliest checkpoint whose last_turn_ts >= the card's timestamp.
288	    for a in authors {
289	        if a.last_turn_ts >= dt {
290	            return Some(a.label.clone());
291	        }
292	    }
293	    // Card's timestamp is past every checkpoint we've seen — attribute to
294	    // the most recent author (latest checkpoint).
295	    authors.last().map(|a| a.label.clone())
296	}
297	
298	fn git_config_user(cwd: &str) -> Option<String> {
299	    for key in ["user.name", "user.email"] {
300	        let mut cmd = std::process::Command::new("git");
301	        cmd.args(["config", key]);
302	        if !cwd.is_empty() && std::path::Path::new(cwd).exists() {
303	            cmd.current_dir(cwd);
304	        }
305	        if let Some(s) = cmd.output().ok()
306	            .filter(|o| o.status.success())
307	            .and_then(|o| String::from_utf8(o.stdout).ok())
308	            .map(|s| s.trim().to_string())
309	            .filter(|s| !s.is_empty())
310	        {
311	            return Some(s);
312	        }
313	    }
314	    None
315	}
316	
317	fn fetch_checkpoints(session_id: &str) -> Vec<CheckpointData> {
318	    let Ok(conn) = crate::db::connect() else { return Vec::new(); };
319	    let Ok(mut stmt) = conn.prepare(
320	        "SELECT checkpoint_id,
321	                COALESCE(commit_sha, ''),
322	                COALESCE(repo_dir, ''),
323	                COALESCE(commit_message, ''),
324	                last_turn_ts,
325	                COALESCE(author_name, ''),
326	                COALESCE(author_email, ''),
327	                COALESCE(files_touched, '[]'),
328	                COALESCE(token_usage, ''),
329	                COALESCE(initial_attribution, ''),
330	                COALESCE(model, '')
331	           FROM checkpoints
332	          WHERE session_id = ?1
333	       ORDER BY last_turn_ts ASC"
334	    ) else { return Vec::new(); };
335	
336	    let rows = stmt.query_map([session_id], |row| {
337	        Ok((
338	            row.get::<_, String>(0)?,
339	            row.get::<_, String>(1)?,
340	            row.get::<_, String>(2)?,
341	            row.get::<_, String>(3)?,
342	            row.get::<_, String>(4)?,
343	            row.get::<_, String>(5)?,
344	            row.get::<_, String>(6)?,
345	            row.get::<_, String>(7)?,
346	            row.get::<_, String>(8)?,
347	            row.get::<_, String>(9)?,
348	            row.get::<_, String>(10)?,
349	        ))
350	    });
351	    let Ok(rows) = rows else { return Vec::new(); };
352	
353	    let mut out = Vec::new();
354	    for (seq, r) in rows.flatten().enumerate() {
355	        let (checkpoint_id, commit_sha, repo_dir, commit_message, last_turn_ts,
356	             author_name, author_email, files_json, token_json, attr_json, model) = r;
357	        let number = (seq + 1) as u32;
358	
359	        let files_touched: Vec<String> = serde_json::from_str(&files_json).unwrap_or_default();
360	
361	        let token_usage = serde_json::from_str::<serde_json::Value>(&token_json).ok()
362	            .and_then(|v| {
363	                Some(TokenUsage {
364	                    input_tokens:          v["input_tokens"].as_i64().unwrap_or(0),
365	                    cache_creation_tokens: v["cache_creation_tokens"].as_i64().unwrap_or(0),
366	                    cache_read_tokens:     v["cache_read_tokens"].as_i64().unwrap_or(0),
367	                    output_tokens:         v["output_tokens"].as_i64().unwrap_or(0),
368	                    api_call_count:        v["api_call_count"].as_i64().unwrap_or(0),
369	                })
370	            });
371	
372	        let initial_attribution = serde_json::from_str::<serde_json::Value>(&attr_json).ok()
373	            .and_then(|v| {
374	                Some(InitialAttribution {
375	                    human_added:         v["human_added"].as_i64().unwrap_or(0),
376	                    human_modified:      v["human_modified"].as_i64().unwrap_or(0),
377	                    human_removed:       v["human_removed"].as_i64().unwrap_or(0),
378	                    total_committed:     v["total_committed"].as_i64().unwrap_or(0),
379	                    total_lines_changed: v["total_lines_changed"].as_i64().unwrap_or(0),
380	                    agent_percentage:    v["agent_percentage"].as_f64().unwrap_or(0.0),
381	                })
382	            });
383	
384	        out.push(CheckpointData {
385	            number: number as u32,
386	            checkpoint_id,
387	            commit_sha,
388	            repo_dir,
389	            commit_message,
390	            last_turn_ts,
391	            author_name,
392	            author_email,
393	            files_touched,
394	            token_usage,
395	            initial_attribution,
396	            model,
397	        });
398	    }
399	    out
400	}
401	
402	fn card_ts(card: &Card) -> Option<&str> {
403	    match card {
404	        Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => Some(ts),
405	        _ => None,
406	    }
407	}
408	
409	fn insert_checkpoints(cards: &mut Vec<Card>, checkpoints: Vec<CheckpointData>) {
410	    // Process in reverse so earlier insertions don't shift later positions.
411	    for cp in checkpoints.into_iter().rev() {
412	        // Find the last card whose timestamp is ≤ this checkpoint's last turn.
413	        let pos = cards.iter().rposition(|c| {
414	            card_ts(c).map_or(false, |ts| ts <= cp.last_turn_ts.as_str())
415	        });
416	        let mut insert_at = pos.map(|i| i + 1).unwrap_or(cards.len());
417	        // Advance past ToolRound cards and any AsstMsg cards (away summary) that
418	        // belong to the same turn — they have no timestamp or a ts ≤ last_turn_ts.
419	        while insert_at < cards.len() {
420	            match &cards[insert_at] {
421	                Card::ToolRound { .. } => { insert_at += 1; }
422	                Card::AsstMsg { ts, .. } if ts.as_str() <= cp.last_turn_ts.as_str() => { insert_at += 1; }
423	                _ => break,
424	            }
425	        }
426	        cards.insert(insert_at, Card::Checkpoint(cp));
427	    }
428	}
429	
430	fn find_session(id: &str) -> Option<PathBuf> {
431	    let p = PathBuf::from(id);
432	    if p.exists() { return Some(p); }
433	    if let Ok(home) = std::env::var("HOME") {
434	        let projects = PathBuf::from(&home).join(".claude/projects");
435	        if let Ok(entries) = std::fs::read_dir(&projects) {
436	            for entry in entries.flatten() {
437	                let candidate = entry.path().join(format!("{id}.jsonl"));
438	                if candidate.exists() { return Some(candidate); }
439	            }
440	        }
441	    }
442	    // Fall back to extracting the latest checkpoint's full.jsonl from the
443	    // entire/checkpoints/v1 branch. Used when this session was authored on
444	    // another machine and never produced a local Claude Code log.
445	    extract_from_checkpoint(id)
446	}
447	
448	fn extract_from_checkpoint(session_id: &str) -> Option<PathBuf> {
449	    let conn = crate::db::connect().ok()?;
450	    let jsonl_path: String = conn.query_row(
451	        "SELECT jsonl_path FROM checkpoints
452	         WHERE session_id = ?1
453	           AND jsonl_path IS NOT NULL
454	         ORDER BY last_turn_ts DESC
455	         LIMIT 1",
456	        [session_id],
457	        |row| row.get(0),
458	    ).ok()?;
459	
460	    // The stored `repo_dir` is whichever repo's index pass last wrote this
461	    // checkpoint row — sometimes stale (the file may since have been removed
462	    // from that repo's branch, or the same file lives in multiple repos'
463	    // shared checkpoint branch). Try the recorded repo_dir first, then fall
464	    // back to every other tracked repo. Whichever clone actually has the path
465	    // in its checkpoint branch wins.
466	    let preferred: Option<String> = conn.query_row(
467	        "SELECT repo_dir FROM checkpoints
468	         WHERE session_id = ?1 AND repo_dir IS NOT NULL
469	         ORDER BY last_turn_ts DESC LIMIT 1",
470	        [session_id], |row| row.get(0),
471	    ).ok();
472	
473	    let mut candidates: Vec<String> = Vec::new();
474	    if let Some(p) = preferred { candidates.push(p); }
475	    if let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") {
476	        if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
477	            for r in rows.flatten() {
478	                if !candidates.contains(&r) { candidates.push(r); }
479	            }
480	        }
481	    }
482	
483	    let bytes = candidates.iter()
484	        .find_map(|dir| crate::commands::index::git_show(dir, &jsonl_path).ok())?;
485	
486	    let home = std::env::var("HOME").ok()?;
487	    let cache_dir = PathBuf::from(&home).join(".gossamer").join("sessions");
488	    std::fs::create_dir_all(&cache_dir).ok()?;
489	    let cache_path = cache_dir.join(format!("{session_id}.jsonl"));
490	    std::fs::write(&cache_path, &bytes).ok()?;
491	    Some(cache_path)
492	}
