825	fn visible_width(s: &str) -> usize {
826	    let mut w = 0usize;
827	    let mut chars = s.chars().peekable();
828	    while let Some(c) = chars.next() {
829	        if c == '\x1b' {
830	            for nc in chars.by_ref() {
831	                if nc.is_ascii_alphabetic() { break; }
832	            }
833	        } else {
834	            w += 1;
835	        }
836	    }
837	    w
838	}
