840	fn fmt_num(n: i64) -> String {
841	    let s = n.abs().to_string();
842	    let mut out = String::new();
843	    for (i, ch) in s.chars().rev().enumerate() {
844	        if i > 0 && i % 3 == 0 { out.push(','); }
845	        out.push(ch);
846	    }
847	    if n < 0 { out.push('-'); }
848	    out.chars().rev().collect()
849	}
