851	fn render_checkpoint_header(cp: &CheckpointData, expanded: bool, w: usize) -> String {
852	    let t = crate::theme::get();
853	    let arrow = if expanded { "▾" } else { "▸" };
854	    let short_id = if cp.checkpoint_id.len() >= 8 {
855	        &cp.checkpoint_id[..8]
856	    } else {
857	        cp.checkpoint_id.as_str()
858	    };
859	    let ts_part = if !cp.last_turn_ts.is_empty() {
860	        format!("  \x1b[{cd}m{}\x1b[0m\x1b[{bg}m", rel_time(&cp.last_turn_ts),
861	            cd = t.checkpoint_dim, bg = t.checkpoint_bg)
862	    } else {
863	        String::new()
864	    };
865	    let id_part = if short_id.is_empty() {
866	        String::new()
867	    } else {
868	        format!("  \x1b[{cd}m{short_id}\x1b[0m\x1b[{bg}m",
869	            cd = t.checkpoint_dim, bg = t.checkpoint_bg)
870	    };
871	
872	    // Measure fixed parts (everything except the commit message) to know how
873	    // much space is left for the message without overflowing the terminal.
874	    let fixed = format!(
875	        "  {arrow} \x1b[{cl}mcheckpoint\x1b[0m\x1b[{bg}m #{}{id_part}\x1b[{ct}m\x1b[0m\x1b[{bg}m{ts_part}",
876	        cp.number,
877	        cl = t.checkpoint_label, bg = t.checkpoint_bg, ct = t.checkpoint_text,
878	    );
879	    let fixed_vis = visible_width(&fixed);
880	    let msg = if !cp.commit_message.is_empty() {
881	        let avail = w.saturating_sub(fixed_vis).saturating_sub(2); // 2 for the "  " prefix
882	        if avail > 0 {
883	            // Use only the subject line — the full body contains newlines which
884	            // break terminal row layout and corrupt everything below.
885	            let subject = cp.commit_message.lines().next().unwrap_or("").trim();
886	            let text: String = subject.chars().take(avail).collect();
887	            if !text.is_empty() { format!("  {text}") } else { String::new() }
888	        } else {
889	            String::new()
890	        }
891	    } else {
892	        String::new()
893	    };
894	
895	    let content = format!(
896	        "  {arrow} \x1b[{cl}mcheckpoint\x1b[0m\x1b[{bg}m #{}{id_part}\x1b[{ct}m{msg}\x1b[0m\x1b[{bg}m{ts_part}",
897	        cp.number,
898	        cl = t.checkpoint_label, bg = t.checkpoint_bg, ct = t.checkpoint_text,
899	    );
900	    let vis = visible_width(&content);
901	    let pad = w.saturating_sub(vis);
902	    format!("\x1b[{bg}m{content}{}\x1b[0m", " ".repeat(pad), bg = t.checkpoint_bg)
903	}
