911	fn render_checkpoint_stats(cp: &CheckpointData) -> Vec<String> {
912	    let t = crate::theme::get();
913	    let mut lines = Vec::new();
914	
915	    if let Some(tu) = &cp.token_usage {
916	        lines.push(format!("  \x1b[{lb}mTokens\x1b[0m", lb = t.label));
917	        lines.push(format!(
918	            "    \x1b[{pr}m{} in  \x1b[0m\x1b[{dm}m·\x1b[0m  \x1b[{pr}m{} out  \x1b[0m\x1b[{dm}m·\x1b[0m  \x1b[{pr}m{} calls\x1b[0m",
919	            fmt_num(tu.input_tokens), fmt_num(tu.output_tokens), fmt_num(tu.api_call_count),
920	            pr = t.text_primary, dm = t.text_dim,
921	        ));
922	        if tu.cache_creation_tokens > 0 || tu.cache_read_tokens > 0 {
923	            lines.push(format!(
924	                "    \x1b[{dm}m{} cache-new  ·  {} cache-read\x1b[0m",
925	                fmt_num(tu.cache_creation_tokens), fmt_num(tu.cache_read_tokens),
926	                dm = t.text_dim,
927	            ));
928	        }
929	        lines.push(String::new());
930	    }
931	
932	    if let Some(ia) = &cp.initial_attribution {
933	        lines.push(format!("  \x1b[{lb}mLines\x1b[0m", lb = t.label));
934	        let pct = format!("{:.0}%", ia.agent_percentage);
935	        let human_total = ia.human_added + ia.human_modified + ia.human_removed;
936	        lines.push(format!(
937	            "    \x1b[{pr}magent {pct}  ({} committed)\x1b[0m  \x1b[{dm}m{} total changed  ·  {} human\x1b[0m",
938	            fmt_num(ia.total_committed), fmt_num(ia.total_lines_changed), fmt_num(human_total),
939	            pr = t.text_primary, dm = t.text_dim,
940	        ));
941	        lines.push(String::new());
942	    }
943	
944	    let author = if !cp.author_name.is_empty() { &cp.author_name }
945	                 else if !cp.author_email.is_empty() { &cp.author_email }
946	                 else { "" };
947	    if !author.is_empty() || !cp.model.is_empty() {
948	        let author_part = if !author.is_empty() {
949	            format!("\x1b[{dm}m{author}\x1b[0m", dm = t.text_dim)
950	        } else { String::new() };
951	        let model_part = if !cp.model.is_empty() {
952	            format!("  \x1b[{dm}m{}\x1b[0m", cp.model, dm = t.text_dim)
953	        } else { String::new() };
954	        lines.push(format!("  {author_part}{model_part}"));
955	        lines.push(String::new());
956	    }
957	
958	    lines
959	}
