983	/// Fetch the diff for `file` in `commit_sha`, colorised with ANSI SGR.
984	fn fetch_file_diff(commit_sha: &str, repo_dir: &str, file: &str) -> Vec<String> {
985	    use std::process::Command;
986	    let t = crate::theme::get();
987	    if commit_sha.is_empty() {
988	        return vec![format!("      \x1b[{ft}m(no commit SHA available)\x1b[0m", ft = t.text_faint)];
989	    }
990	    let Some(actual_dir) = resolve_repo_for_commit(commit_sha, repo_dir) else {
991	        return vec![format!("      \x1b[{ft}m(commit not found in any registered repo)\x1b[0m", ft = t.text_faint)];
992	    };
993	    let out = Command::new("git")
994	        .args(["show", commit_sha, "--", file])
995	        .current_dir(&actual_dir)
996	        .output();
997	    let Ok(out) = out else {
998	        return vec![format!("      \x1b[{ft}m(could not run git show)\x1b[0m", ft = t.text_faint)];
999	    };
1000	    let raw = String::from_utf8_lossy(&out.stdout);
1001	    let mut lines: Vec<String> = Vec::new();
1002	    let mut in_hunk = false;
1003	    for line in raw.lines() {
1004	        if line.starts_with("@@") { in_hunk = true; }
1005	        if !in_hunk { continue; }
1006	        let colored = if line.starts_with('+') && !line.starts_with("+++") {
1007	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.fresh)
1008	        } else if line.starts_with('-') && !line.starts_with("---") {
1009	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.error)
1010	        } else if line.starts_with("@@") {
1011	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.label)
1012	        } else {
1013	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.text_dim)
1014	        };
1015	        lines.push(colored);
1016	        if lines.len() >= 300 {
1017	            lines.push(format!("      \x1b[{ft}m… truncated\x1b[0m", ft = t.text_faint));
1018	            break;
1019	        }
1020	    }
1021	    if lines.is_empty() {
1022	        lines.push(format!("      \x1b[{ft}m(empty diff)\x1b[0m", ft = t.text_faint));
1023	    }
1024	    lines
1025	}
