1261	fn rel_time(iso: &str) -> String {
1262	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return iso.to_string(); };
1263	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
1264	    if secs < 604_800 {
1265	        match secs {
1266	            s if s < 60     => "just now".into(),
1267	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
1268	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
1269	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),

