/// Copy a session's checkpoint-branch transcript into Claude Code's own
/// project-directory convention (`~/.claude/projects/<cwd-with-slashes-as-
/// dashes>/<id>.jsonl`) so `claude --resume <id>` picks it up directly from
/// `dir`. This restores conversational *context* only — it doesn't require
/// (or check for) any matching commit/branch, unlike `entire session resume`.
/// If the session's code was never pushed to `dir`'s branch, Claude will have
/// history that doesn't match files on disk; that's an accepted tradeoff for
/// being able to load context at all when the code isn't locally available.
fn materialize_transcript_for_claude(session_id: &str, dir: &str) -> Option<String> {
    let cached = extract_from_checkpoint(session_id)?;
    let home = std::env::var("HOME").ok()?;
    let abs_dir = std::fs::canonicalize(dir).unwrap_or_else(|_| PathBuf::from(dir));
    let encoded = abs_dir.to_string_lossy().replace('/', "-");
    let project_dir = PathBuf::from(&home).join(".claude/projects").join(encoded);
    std::fs::create_dir_all(&project_dir).ok()?;
    let dest = project_dir.join(format!("{session_id}.jsonl"));
    if !dest.exists() {
        std::fs::copy(&cached, &dest).ok()?;
    }
    Some(abs_dir.to_string_lossy().to_string())
}

/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found and no
/// local repo/branch can be resolved from the DB either.
pub fn resume_session(session_id: &str, fallback_cwd: &str) {
    use std::os::unix::process::CommandExt;
    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
            fallback_cwd.to_string()
        } else {
            session_cwd
        };
        let err = std::process::Command::new("claude")
            .arg("--resume")
            .arg(session_id)
            .current_dir(&launch_dir)
            .exec();
        eprintln!("exec failed: {err}");
        // exec failed — fall back to entire resume, checking out the session branch first
        resume_via_entire(&launch_dir, &session_branch);
        return;
    }

    // No local Claude transcript — this session never ran on this machine.
    // Prefer the locally-tracked repo directory (resolved from the DB, not
    // the foreign cwd the caller may have passed) as the place to load context.
    let db_repo = db_session_repo_and_branch(session_id);
    let context_dir = db_repo.as_ref()
        .map(|(d, _)| d.as_str())
        .filter(|d| std::path::Path::new(d).exists())
        .or_else(|| Some(fallback_cwd).filter(|d| std::path::Path::new(d).exists()));

    if let Some(dir) = context_dir {
        if let Some(launch_dir) = materialize_transcript_for_claude(session_id, dir) {
            let err = std::process::Command::new("claude")
                .arg("--resume")
                .arg(session_id)
                .current_dir(&launch_dir)
                .exec();
            eprintln!("exec failed: {err}");
            return;
        }
    }

    // No transcript could be materialized either (checkpoint truly isn't
    // found anywhere) — fall back to `entire`, which will report why.
    if let Some((repo_dir, branch)) = db_repo {
        resume_via_entire(&repo_dir, &branch);
    } else {
        resume_via_entire(fallback_cwd, "");
    }
}
